import shutil
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

data_ws = vals["Data"]
report_vals = vals["Report"]
report_out = wb["Report"]

def norm_truck(value):
    if value is None:
        return ""
    if isinstance(value, float) and value.is_integer():
        return str(int(value))
    return str(value).strip()

# Sum quantities by truck ID from the Data sheet
truck_qty = {}
for row in range(3, data_ws.max_row + 1):
    truck = norm_truck(data_ws.cell(row, 3).value)
    qty = data_ws.cell(row, 4).value
    if truck and isinstance(qty, (int, float)) and not isinstance(qty, bool):
        truck_qty[truck] = truck_qty.get(truck, 0.0) + float(qty)

# Fill Report!D3:D10
results = []
for row in range(3, 11):
    trucks_cell = report_vals.cell(row, 3).value
    total = 0.0

    if trucks_cell is not None:
        for part in str(trucks_cell).split(","):
            truck = norm_truck(part)
            if truck:
                total += truck_qty.get(truck, 0.0)

    total = round(total, 2)
    report_out.cell(row, 4).value = total
    results.append((row, total))

print("Computed Report D3:D10:", results)

wb.save(OUT)
